  private static final String REL_URL="https://openstax.org/books/university-physics-volume-3/pages/5-key-equations";
  private static final String PHOTON="OpenStax, University Physics Vol. 3, photon momentum p=E/c";
  private static final String PHOTON_URL="https://openstax.org/books/university-physics-volume-3/pages/6-key-equations";
  private static final String NIST_SIGMA="https://physics.nist.gov/cgi-bin/cuu/Value?sigma%7Csearch_for=stefan+boltzmann";
  private static final String TEXT="OpenStax University Physics Vol. 1, classical mechanics";
  private static final String THERMO="OpenStax University Physics Vol. 2, thermodynamics";
  private static final String THERMO_URL="https://openstax.org/books/university-physics-volume-2/pages/2-key-equations";
  private static final String CONDUCTION_URL="https://openstax.org/books/university-physics-volume-2/pages/1-summary";
